export const VERSION='1.0.0', STORAGE_KEY='qf-studio-chapter-04-v1';
export const STEPS=[['start','Set up your evidence',10],['probability','Count and complement',25],['centre','Mean and median',25],['spread','Spread and quantiles',30],['correlation','Pair the observations',25],['lab','Resample and question',35],['assessment','Independent transfer',20],['finish','Save a statistics card',10]];
export const DATA=[{date:'2025-01',a:-3,b:-2},{date:'2025-02',a:-1,b:0},{date:'2025-03',a:0,b:1},{date:'2025-04',a:1,b:-1},{date:'2025-05',a:2,b:3},{date:'2025-06',a:7,b:5}];
export const A=DATA.map(r=>r.a),B=DATA.map(r=>r.b);
function numbers(x,min=1){if(!Array.isArray(x)||x.length<min||x.some(v=>typeof v!=='number'||!Number.isFinite(v)))throw Error(`Supply at least ${min} finite numbers.`);return x;}
export function mean(x){numbers(x);return x.reduce((a,b)=>a+b,0)/x.length;}
export function quantile(x,p){numbers(x);if(typeof p!=='number'||!Number.isFinite(p)||p<0||p>1)throw Error('Quantile probability must be 0–1.');const s=[...x].sort((a,b)=>a-b),h=(s.length-1)*p,i=Math.floor(h);return s[i]+(h-i)*((s[i+1]??s[i])-s[i]);}
export function sampleSD(x){numbers(x,2);if(x.every(v=>v===x[0]))return 0;const m=mean(x);return Math.sqrt(x.reduce((s,v)=>s+(v-m)**2,0)/(x.length-1));}
export function lossFrequency(x){numbers(x);return x.filter(v=>v<0).length/x.length;}
export function correlation(x,y){numbers(x,2);numbers(y,2);if(x.length!==y.length)throw Error('Match aligned observations before calculating.');if(x.every(v=>v===x[0])||y.every(v=>v===y[0]))return null;const mx=mean(x),my=mean(y),xx=x.reduce((s,v)=>s+(v-mx)**2,0),yy=y.reduce((s,v)=>s+(v-my)**2,0);if(xx===0||yy===0)return null;return x.reduce((s,v,i)=>s+(v-mx)*(y[i]-my),0)/Math.sqrt(xx*yy);}
export function pairedCorrelation(left,right){if(!Array.isArray(left)||!Array.isArray(right)||left.length!==right.length||left.length<2)throw Error('Use matching date rows.');if(new Set(left.map(r=>r.date)).size!==left.length||left.some((r,i)=>typeof r.date!=='string'||r.date!==right[i].date))throw Error('Dates must be unique and aligned in the same order.');return correlation(left.map(r=>r.value),right.map(r=>r.value));}
export function resample(seed,count=100){if(!Number.isInteger(seed)||seed<1||seed>999999||!Number.isInteger(count)||count<2||count>500)throw Error('Use seed 1–999999 and 2–500 repetitions.');let z=seed>>>0;const random=()=>{z=(Math.imul(1664525,z)+1013904223)>>>0;return z/4294967296;};return Array.from({length:count},(_,i)=>{const indices=Array.from({length:A.length},()=>Math.floor(random()*A.length));return {replicate:i+1,indices,values:indices.map(j=>A[j]),mean:mean(indices.map(j=>A[j]))};});}
const q=(id,title,answer,hint,critical=false,type='number')=>({id,title,answer,hint,critical,type,tolerance:.011});
export const PRACTICE={
 probability:[q('p1','Of six A months, two are strictly negative. Observed loss frequency (0–1)?',2/6,'Count −3 and −1; divide by six. Zero is not a loss.'),q('p2','New case: returns [−2, 0, 4, 1]. Frequency of a nonnegative return (0–1)?',.75,'The complement includes zero: 1 − 1/4.')],
 centre:[q('c1','A returns [−3, −1, 0, 1, 2, 7]. Arithmetic mean (%)?',1,'Add all six returns (=6), divide by 6.'),q('c2','New case [−4, 0, 2, 2, 10]. Median (%)?',2,'Sort, then select the middle third value.')],
 spread:[q('s1','For [−2, 0, 2], sample standard deviation (percentage points)?',2,'Mean=0; squared deviations sum to 8; divide by n−1=2, then take the square root.'),q('s2','New case [0, 10, 20, 40]. 25th percentile under h=(n−1)p linear interpolation (%)?',7.5,'h=3×.25=.75: 75% of the way from 0 to 10.')],
 correlation:[q('r1','For aligned pairs x=[−1,0,1], y=[−2,0,2], Pearson correlation?',1,'The points lie exactly on a line with positive slope.'),q('r2','A positive correlation proves which statement? Enter 1 for association in this sample; 2 for causation; 3 for a guaranteed future relationship.',1,'Choose the limited claim: sample association does not establish a cause.',true,'choice')]
};
export const ASSESSMENTS=[q('a1','New returns [−6,−2,0,4,9]. Observed strictly negative frequency (0–1)?',.4,'Two negative observations / five.'),q('a2','Complement: nonnegative frequency (0–1)?',.6,'One minus .4; zero belongs to the complement.'),q('a3','For that same five-return series, arithmetic mean (%)?',1,'The sum is 5 and n is 5.'),q('a4','For [−4,0,4], sample standard deviation (percentage points)?',4,'Sum of squared deviations 32 / (3−1) = 16; square root =4.',true),q('a5','For [0,4,8,20], the 75th percentile under h=(n−1)p interpolation (%)?',11,'h=2.25, one quarter of the way from 8 to 20.'),q('a6','If either paired series has zero variance, enter 1 for correlation=0; 2 for undefined.',2,'The denominator is zero, so correlation is undefined.',true,'choice'),q('a7','After resampling six invented months, enter 1 for guaranteed future probability; 2 for sensitivity conditional on these observations.',2,'Resampling reuses only this tiny observed sample and its assumptions.',true,'choice'),q('a8','Before computing correlation enter 1 to align matching dates; 2 to sort each asset independently.',1,'Preserve original date pairs. Sorting each asset creates false pairings.',true,'choice')];
export function check(q,raw){if(typeof raw==='boolean'||raw===null||String(raw??'').trim()==='')return false;const n=Number(raw);return Number.isFinite(n)&&Math.abs(n-q.answer)<=(q.type==='choice'?0:q.tolerance);}
export function grade(answers){const details=ASSESSMENTS.map(q=>({id:q.id,correct:check(q,answers[q.id]),critical:q.critical}));return {score:details.filter(d=>d.correct).length,passed:details.filter(d=>d.correct).length>=7&&details.filter(d=>d.critical).every(d=>d.correct),details};}
export const freshState=()=>({version:VERSION,fields:{},done:{},checked:{},practiceAttempts:[],runs:[],attempts:[]});
export function invalidate(s,id){for(const [step,qs]of Object.entries(PRACTICE))if(qs.some(q=>q.id===id)||id===step+'Reflection'||id===step+'Criteria'){delete s.done[step];delete s.checked[id];}if(id.startsWith('quiz-')||id==='revision'){delete s.done.assessment;s.fields.quizDirty='yes';}if(['prediction','seed','hand','labReflection','labCriteria'].includes(id)){delete s.done.lab;if(id==='hand')s.fields.handVerified='';}if(id.startsWith('card'))delete s.done.finish;if(id==='setup')delete s.done.start;}
export function labEvidence(s){const run=s.runs.at(-1);return !!run&&run.prediction===s.fields.prediction&&run.seed===Number(s.fields.seed??42)&&new Set(s.runs.map(r=>r.seed)).size>=2&&check({answer:run.rows[0].mean,tolerance:.011},s.fields.hand)&&s.fields.handVerified==='yes'&&(s.fields.labReflection||'').trim().length>=50&&s.fields.labCriteria==='yes';}
export function restoreState(raw){try{const s=JSON.parse(raw),record=v=>v&&typeof v==='object'&&!Array.isArray(v);if(s?.version!==VERSION||!record(s.fields)||Object.values(s.fields).some(v=>typeof v!=='string')||!record(s.done)||!record(s.checked)||Object.values(s.done).some(v=>typeof v!=='boolean')||Object.values(s.checked).some(v=>typeof v!=='boolean')||!Array.isArray(s.runs)||!Array.isArray(s.attempts))throw Error();const restored={...freshState(),fields:s.fields,practiceAttempts:(Array.isArray(s.practiceAttempts)?s.practiceAttempts:[]).filter(a=>record(a)&&typeof a.id==='string'&&typeof a.raw==='string'&&typeof a.correct==='boolean'&&typeof a.time==='string'),runs:s.runs.map(r=>{if(typeof r.prediction!=='string'||typeof r.time!=='string')throw Error();return {seed:r.seed,prediction:r.prediction,time:r.time,rows:resample(r.seed)};}),attempts:s.attempts.map(a=>{if(!record(a.answers)||Object.values(a.answers).some(v=>typeof v!=='string')||typeof a.time!=='string'||(a.revision!==undefined&&typeof a.revision!=='string'))throw Error();return {...a,...grade(a.answers)};})};/* Completion is re-derived from current evidence, never accepted from stored booleans. */for(const[step,qs]of Object.entries(PRACTICE)){for(const q of qs)if(s.checked[q.id]===true&&check(q,s.fields[q.id]))restored.checked[q.id]=true;if(qs.every(q=>restored.checked[q.id])&&(s.fields[step+'Reflection']||'').trim().length>=30&&s.fields[step+'Criteria']==='yes')restored.done[step]=true;}if(s.fields.setup==='yes')restored.done.start=true;const latest=restored.attempts.at(-1);if(latest?.passed&&s.fields.quizDirty!=='yes'&&latest.revision?.length>=30&&ASSESSMENTS.every(q=>latest.answers[q.id]===s.fields['quiz-'+q.id]))restored.done.assessment=true;if(['cardMethod','cardCheck','cardLimit'].every(k=>(s.fields[k]||'').trim().length>=30)&&s.fields.cardCriteria==='yes')restored.done.finish=true;if(labEvidence(restored))restored.done.lab=true;return restored;}catch{return freshState();}}
